// Newest episodes with an audio enclosure, capped per run
const s = $('Set podcast settings').first().json;
const strip = h => String(h || '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
return $input.all().map(i => i.json)
  .filter(e => e.enclosure?.url && (/^audio\//i.test(e.enclosure.type || '') || (!e.enclosure.type && /\.(mp3|m4a|aac|ogg|wav)(\?|$)/i.test(e.enclosure.url))))
  .sort((a, b) => Date.parse(b.isoDate || b.pubDate) - Date.parse(a.isoDate || a.pubDate))
  .slice(0, Number(s.max_episodes_per_run) || 1)
  .map(e => ({ json: { episode_id: e.guid || e.link || e.enclosure.url, title: e.title, show_name: s.show_name,
    published: e.isoDate ? DateTime.fromISO(e.isoDate).toFormat('d LLL yyyy') : (e.pubDate || ''),
    duration: e['itunes:duration'] || '', audio_url: e.enclosure.url, audio_bytes: Number(e.enclosure.length) || 0,
    description: strip(e.content || e.contentSnippet || e['itunes:summary']).slice(0, 3000) } }));

// Use the Gemini transcript, or fall back to the description when transcription failed
return $input.all().map((item, i) => {
  const ep = $('Skip episodes already done').itemMatching(i).json;
  const text = (item.json.content?.parts || []).map(p => p.text || '').join('\n').trim();
  const ok = text.length > 500 && !item.json.error;
  return { json: { ...ep, transcript: ok ? text.slice(0, 400000) : ep.description,
    transcript_source: ok ? 'audio' : 'description', transcript_chars: text.length } };
});

