// Validate chapters against YouTube's rules (first at 00:00, >= 3 chapters, >= 10 s apart, inside the episode)
const toSec = t => String(t || '').split(':').map(Number).reduce((a, n) => a * 60 + (n || 0), 0);
const fmt = s => { const h = Math.floor(s / 3600), m = Math.floor(s % 3600 / 60), x = Math.floor(s % 60);
  return (h ? h + ':' + String(m).padStart(2, '0') : String(m).padStart(2, '0')) + ':' + String(x).padStart(2, '0'); };
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return $input.all().map((item, i) => {
  const ep = $('Prepare transcript').itemMatching(i).json;
  const o = item.json.output || {};
  const dur = toSec(ep.duration) || 0;
  let ch = (o.chapters || []).map(c => ({ s: toSec(c.start), title: String(c.title || '').trim() }))
    .filter(c => c.title && (!dur || c.s < dur)).sort((a, b) => a.s - b.s);
  ch = ch.filter((c, k) => k === 0 || c.s - ch[k - 1].s >= 10);
  if (ch.length && ch[0].s !== 0) ch.unshift({ s: 0, title: 'Intro' });
  const chaptersOk = ch.length >= 3;
  const chapterText = chaptersOk ? ch.map(c => `${fmt(c.s)} ${c.title}`).join('\n') : '';
  const youtubeDescription = `${o.show_notes || ''}\n\n${chapterText ? 'Chapters\n' + chapterText + '\n\n' : ''}${(o.key_takeaways || []).map(t => '• ' + t).join('\n')}`;
  const li = a => (a || []).map(x => `<li>${esc(x)}</li>`).join('');
  const html = `<h2>${esc(ep.title)}</h2><p><i>${esc(ep.show_name)} · ${esc(ep.published)} · ${esc(ep.duration || '')}</i></p>
<p>${esc(o.summary)}</p>${ep.transcript_source === 'description' ? '<p><b>⚠️ Audio could not be transcribed; notes are based on the episode description only.</b></p>' : ''}
<h3>Show notes</h3><p>${esc(o.show_notes)}</p><h3>Key takeaways</h3><ul>${li(o.key_takeaways)}</ul>
<h3>Chapters</h3><pre>${esc(chapterText || 'Not enough reliable timestamps for chapters.')}</pre>
<h3>Title ideas</h3><ol>${li(o.title_ideas)}</ol>
<h3>Quotes</h3><ul>${(o.quotes || []).map(q => `<li>[${esc(q.time)}] ${esc(q.speaker)}: "${esc(q.text)}"</li>`).join('')}</ul>
<h3>Social posts</h3><p><b>X:</b> ${esc(o.social?.x_post)}</p><p><b>LinkedIn:</b><br>${esc(o.social?.linkedin_post).replace(/\n/g, '<br>')}</p><p><b>Instagram:</b><br>${esc(o.social?.instagram_caption)}</p>
<h3>Newsletter blurb</h3><p>${esc(o.newsletter_blurb)}</p><h3>YouTube description</h3><pre>${esc(youtubeDescription)}</pre>`;
  return { json: { episode_id: ep.episode_id, title: ep.title, published: ep.published, audio_url: ep.audio_url,
    transcript_source: ep.transcript_source, chapters: chapterText, chapters_ok: chaptersOk, summary: o.summary || '',
    show_notes: o.show_notes || '', title_ideas: (o.title_ideas || []).join(' | '), x_post: o.social?.x_post || '',
    linkedin_post: o.social?.linkedin_post || '', instagram_caption: o.social?.instagram_caption || '',
    newsletter_blurb: o.newsletter_blurb || '', youtube_description: youtubeDescription, html,
    quotes: (o.quotes || []).map(q => `[${q.time}] ${q.text}`).join(' | '), processed_at: $now.toFormat('yyyy-MM-dd HH:mm') } };
});
